/* @autogenerated */
package net.civeira.phylax.common.algorithms;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

@DisplayName("Slider once its source has been loaded")
class SliderEdgeCasesUnitTest {

  private static Slider<String> slider(List<String> data, int limit) {
    return new SliderTestUnitTest.TestSlider(data.iterator(), limit, new LinkedList<>());
  }

  @Test
  @DisplayName("Should reuse the loaded list on repeated calls to all")
  void shouldReuseLoadedListOnRepeatedAll() {
    // Arrange — a slider over three items
    Slider<String> slider = slider(List.of("a", "b", "c"), 10);

    // Act — load the items twice
    List<String> first = slider.all();
    List<String> second = slider.all();

    // Assert — the second call returns the cached list without reading the source again
    assertSame(first, second, "all() should return the same cached list on repeated calls");
    assertEquals(List.of("a", "b", "c"), second);
  }

  @Test
  @DisplayName("Should slide over the loaded items after all has drained the source")
  void shouldSlideOverLoadedItemsAfterAll() {
    // Arrange — a slider whose source has been drained by all()
    Slider<String> slider = slider(List.of("a", "b", "c"), 10);
    slider.all();

    // Act — slide over the already loaded items
    Iterator<String> it = slider.slide(s -> !"b".equals(s));
    List<String> result = new ArrayList<>();
    it.forEachRemaining(result::add);

    // Assert — the loaded items are used as initial data and filtered
    assertEquals(List.of("a", "c"), result,
        "slide() should iterate the cached items when the source was already loaded");
  }
}
